INSERT INTO movies (slug, title, tagline, synopsis, genres, language, certificate, duration_min, release_date, rating, director, cast_members, formats, status, poster_url) VALUES
    ('monsoon-protocol', 'Monsoon Protocol', 'The storm is the cover. The city is the target.', 'When a cyber-attack cripples Mumbai''s flood-control grid on the wettest night of the year, a suspended police analyst has twelve hours to find the hacker before the sea walls open.', ARRAY['Action', 'Thriller']::text[], 'Hindi', 'UA', 148, '2026-11-06', 8.4, 'Raghav Malhotra', ARRAY['Arjun Sethi', 'Meera Kulkarni', 'Imran Qadri']::text[], ARRAY['2D', 'IMAX', '4DX']::text[], 'now_showing', '/posters/monsoon-protocol.svg'),
    ('the-last-lighthouse', 'The Last Lighthouse', 'Some lights are meant to keep things out.', 'A marine biologist takes a winter post at a remote lighthouse and begins receiving signals from a ship that sank forty years ago.', ARRAY['Mystery', 'Drama']::text[], 'English', 'UA', 121, '2026-10-24', 7.9, 'Elena Marsh', ARRAY['Thomas Avery', 'Clara Whitfield', 'Joon Park']::text[], ARRAY['2D']::text[], 'now_showing', '/posters/the-last-lighthouse.svg'),
    ('kaagaz-ke-sapne', 'Kaagaz Ke Sapne', 'Paper dreams don''t sink. They sail.', 'A ten-year-old from a Varanasi ghat folds a thousand paper boats to win a city art contest and pay for her grandfather''s surgery.', ARRAY['Drama', 'Family']::text[], 'Hindi', 'U', 132, '2026-11-13', 8.8, 'Nandini Iyer', ARRAY['Riya Bansal', 'Om Prakash Tiwari', 'Sushma Rao']::text[], ARRAY['2D']::text[], 'now_showing', '/posters/kaagaz-ke-sapne.svg'),
    ('orbit-9', 'Orbit 9', 'Nine crew. Eight seats home.', 'After a solar flare cripples a research station around Saturn, the crew discovers their rescue capsule was built for one person fewer than they are.', ARRAY['Sci-Fi', 'Thriller']::text[], 'English', 'UA', 139, '2026-11-20', 8.1, 'Marcus Lindqvist', ARRAY['Ava Reyes', 'Daniel Okafor', 'Priya Natarajan']::text[], ARRAY['2D', '3D', 'IMAX']::text[], 'now_showing', '/posters/orbit-9.svg'),
    ('neon-bazaar', 'Neon Bazaar', 'One night. One market. Seven very bad plans.', 'Three friends running a failing electronics stall in Delhi''s night market get mixed up in a diamond heist that everyone, including the thieves, is getting wrong.', ARRAY['Comedy', 'Crime']::text[], 'Hindi', 'UA', 127, '2026-10-31', 7.6, 'Kabir Anand', ARRAY['Vikrant Chopra', 'Sana Mirza', 'Bunty Gill']::text[], ARRAY['2D']::text[], 'now_showing', '/posters/neon-bazaar.svg'),
    ('vettai', 'Vettai', 'In the forest, the hunter becomes the hunted.', 'A forest ranger in the Nilgiris goes after a poaching ring and finds the trail leads back to people she trusts.', ARRAY['Action', 'Adventure']::text[], 'Tamil', 'A', 155, '2026-11-13', 8.3, 'S. Karthikeyan', ARRAY['Lakshmi Varadan', 'Surya Prakash', 'Dev Anbu']::text[], ARRAY['2D', 'IMAX']::text[], 'now_showing', '/posters/vettai.svg'),
    ('silent-frequency', 'Silent Frequency', 'Don''t answer if it calls your name.', 'A late-night radio host starts picking up a station that broadcasts tomorrow''s emergencies, and tonight it is reading out her address.', ARRAY['Horror', 'Thriller']::text[], 'English', 'A', 104, '2026-10-31', 7.4, 'Grace Holloway', ARRAY['Nora Quinn', 'Leo Varga', 'Hannah Cole']::text[], ARRAY['2D', '4DX']::text[], 'now_showing', '/posters/silent-frequency.svg'),
    ('chai-and-chaos', 'Chai & Chaos', 'Two cafés. One street. Zero chill.', 'Rival café owners in Bengaluru wage a war of discounts, reviews and secret recipes until a city food festival forces them to share a stall.', ARRAY['Romance', 'Comedy']::text[], 'Hindi', 'U', 118, '2026-11-20', 7.8, 'Ishita Sen', ARRAY['Karan Mehra', 'Aditi Rao', 'Joseph D''Souza']::text[], ARRAY['2D']::text[], 'now_showing', '/posters/chai-and-chaos.svg'),
    ('kingdom-of-sand', 'Kingdom of Sand', 'Empires fall. Legends rise from the dust.', 'A desert queen of the 14th century unites three warring clans to defend a fortress city against an army ten times their size.', ARRAY['Historical', 'Action', 'Epic']::text[], 'Telugu', 'UA', 172, '2026-12-11', NULL, 'V. Ramachandra Rao', ARRAY['Anushree Reddy', 'Vamsi Krishna', 'Mahesh Varma']::text[], ARRAY['2D', '3D', 'IMAX']::text[], 'coming_soon', '/posters/kingdom-of-sand.svg'),
    ('pixel-hearts', 'Pixel Hearts', 'Game over is just the beginning.', 'When an old arcade is set to be demolished, the characters inside its forgotten games team up to escape into the real world.', ARRAY['Animation', 'Family', 'Adventure']::text[], 'English', 'U', 98, '2026-12-18', NULL, 'Mia Tanaka', ARRAY['Voice: Sam Rivers', 'Voice: Lily Chen', 'Voice: Omar Haddad']::text[], ARRAY['2D', '3D']::text[], 'coming_soon', '/posters/pixel-hearts.svg'),
    ('the-ninth-over', 'The Ninth Over', 'Six balls to change everything.', 'A washed-up fast bowler coaching a small-town women''s cricket team gets one last shot when they reach a national final nobody expected them to play.', ARRAY['Sports', 'Drama']::text[], 'Hindi', 'U', 141, '2027-01-15', NULL, 'Rohan Deshpande', ARRAY['Aakash Rathore', 'Simran Kaur', 'Neha Joshi']::text[], ARRAY['2D', 'IMAX']::text[], 'coming_soon', '/posters/the-ninth-over.svg'),
    ('echoes-of-ladakh', 'Echoes of Ladakh', 'Some journeys take you home.', 'Two estranged brothers ride motorcycles across Ladakh to scatter their father''s ashes at a lake he never told them about.', ARRAY['Drama', 'Adventure']::text[], 'Hindi', 'U', 126, '2026-11-06', 8.6, 'Tenzin Dorje', ARRAY['Rahul Bhatia', 'Varun Thakur', 'Pema Lhamo']::text[], ARRAY['2D']::text[], 'now_showing', '/posters/echoes-of-ladakh.svg')
